import { esc,options } from '../utils.js';
import { button,heading } from './helpers.js';
import { normalizeAppearance,appearancePalette } from './appearance.js';
import { stylePresets } from './styles.js';
export const backgroundPresets=[['default','Original'],['#101828','Noche'],['#18342c','Bosque'],['#27344a','Azul'],['#40314e','Lavanda'],['#f5efe5','Arena'],['#f2f5fa','Nube']];
export const accentPresets=[['#a7edc5','Menta'],['#9ec5ff','Azul'],['#c4b5fd','Lavanda'],['#f6b6c8','Rosa'],['#f7c77d','Ámbar'],['#ffffff','Blanco']];
export function personalizationView(preferences,savedStyles=[],historyCount=0) {
  const p=normalizeAppearance(preferences),palette=appearancePalette(p);
  const select=(key,label,items,disabled=false)=>`<label>${label}<select id="appearance-${key}" data-appearance-key="${key}" ${disabled?'disabled':''}>${options(items,p[key])}</select></label>`;
  const range=(key,label,min,max,value,unit='',disabled=false)=>`<label class="appearance-slider">${label}<output id="appearance-${key}-output">${value}${unit}</output><input type="range" id="appearance-${key}" data-appearance-key="${key}" data-unit="${unit}" min="${min}" max="${max}" step="1" value="${value}" ${disabled?'disabled':''}></label>`;
  const reset=group=>button('reset-appearance-group','Restablecer este apartado',`data-group="${group}"`);
  const color=(key,label,value)=>`<label class="custom-color">${label}<input type="color" id="appearance-${key}" data-appearance-key="${key}" value="${value}"></label>`;
  const swatches=(items,key)=>`<div class="color-swatches" role="group" aria-label="${key==='background'?'Colores de fondo':'Colores de botones'}">${items.map(([value,label])=>`<button type="button" class="color-choice" data-action="appearance-color" data-key="${key}" data-color="${value}" aria-pressed="${p[key]===value}" aria-label="${esc(label)}"><i style="background:${value==='default'?(p.theme==='light'?'#f3f6f5':'#11191c'):value}" aria-hidden="true"></i><span>${esc(label)}</span></button>`).join('')}</div>`;
  return `<div class="toolbar">${button('settings','Volver a ajustes')}${button('undo-appearance','Deshacer cambio',historyCount?'':'disabled')}${button('toggle-appearance-sections','Abrir / cerrar apartados')}</div>`+heading('','Personalización','Elige un estilo o ajústalo a tu gusto. Los cambios se guardan al momento.')+
  `<section class="panel personalization-panel appearance-preview"><div class="day-title"><h2>Vista previa</h2><span class="pill">Ejemplo</span></div><p class="preview-heading">Tu espacio, a tu manera</p><p class="help">Así se ven los colores, el texto y los botones.</p><div class="preview-example"><span class="preview-badge"><span class="brand-icon"><svg class="brand-mark" width="32" height="32" viewBox="0 0 144 144" fill="none" aria-hidden="true"><use href="#ritmo-logo-path"/></svg></span><span class="brand-name">Ritmo</span></span><strong>Tu próximo entrenamiento</strong><span>Una serie más, a tu ritmo.</span><button type="button" class="primary" disabled>Botón de ejemplo</button></div></section>
  <details class="panel personalization-panel" data-view-key="personal-presets" open><summary>Estilos listos para usar</summary><div class="style-presets">${stylePresets.map(s=>`<button type="button" data-action="appearance-preset" data-id="${s.id}" class="style-preset"><i style="background:${s.settings.background||'#11191c'};border-color:${s.settings.accent||'#a7edc5'}" aria-hidden="true"></i><span>${esc(s.name)}</span></button>`).join('')}</div></details>
  <details class="panel personalization-panel" data-view-key="personal-background"><summary>Fondo y degradados</summary>${swatches(backgroundPresets,'background')}${color('background','Color principal',palette.background)}${select('backgroundMode','Tipo de fondo',[['solid','Un color'],['gradient','Degradado de dos colores']])}<div ${p.backgroundMode==='gradient'?'':'hidden'}>${color('gradientEnd','Segundo color',p.gradientEnd)}${range('gradientAngle','Dirección del degradado',0,360,p.gradientAngle,'°')}</div>${select('pattern','Patrón',[['none','Sin patrón'],['dots','Puntos suaves'],['grid','Cuadrícula suave']])}${reset('background')}</details>
  <details class="panel personalization-panel" data-view-key="personal-buttons"><summary>Botones y color de acento</summary>${swatches(accentPresets,'accent')}${color('accent','Color personalizado',p.accent)}<div class="fields">${select('buttonStyle','Estilo de botones',[['solid','Rellenos'],['outline','Solo contorno']])}${select('buttonShape','Forma de botones',[['square','Rectos'],['rounded','Redondeados'],['pill','Cápsula']])}</div>${select('buttonHeight','Tamaño de los botones',[[44,'Compactos · 44 px'],[50,'Normales · 50 px'],[58,'Grandes · 58 px'],[64,'Muy grandes · 64 px']])}<p class="help">El nombre de la app conserva su color y su tipografía.</p>${reset('buttons')}</details>
  <details class="panel personalization-panel" data-view-key="personal-logo"><summary>Símbolo de Ritmo</summary><p class="help">El nombre de la app mantiene su tipografía y color neutro. Estos ajustes afectan solo al símbolo.</p>${select('logoMode','Color del símbolo',[['accent','Igual que los botones'],['custom','Elegir otro color']])}<div ${p.logoMode==='custom'?'':'hidden'}>${color('logoColor','Color propio del símbolo',p.logoColor)}</div><div class="fields">${select('logoSize','Tamaño',[[32,'Pequeño'],[42,'Normal'],[52,'Grande'],[64,'Muy grande']])}${select('logoShape','Forma del fondo',[['square','Recta'],['soft','Redondeada'],['circle','Circular']])}</div>${select('logoTile','Fondo del símbolo',[['auto','Con fondo de contraste'],['none','Transparente, con contraste adaptado']])}${reset('logo')}</details>
  <details class="panel personalization-panel" data-view-key="personal-cards"><summary>Tarjetas y Liquid Glass</summary>${select('glassIntensity','Intensidad del cristal',[['strong','Intenso · más reflejos y transparencia'],['subtle','Discreto']])}${select('glassMotion','Animaciones del cristal',[['expressive','Expresivas · con rebote suave'],['gentle','Suaves']])}${color('cardColor','Color de tarjetas',palette.surface)}${button('appearance-auto-cards','Usar color según el tema')}<div class="fields">${select('corners','Esquinas',[['square','Rectas'],['soft','Suaves'],['rounded','Redondeadas'],['pill','Muy redondeadas']])}${select('shadow','Sombras',[['none','Sin sombra'],['soft','Suaves'],['deep','Marcadas']])}</div><label class="glass-switch"><span><strong>Liquid Glass</strong><small>Transparencia y desenfoque.</small></span><input type="checkbox" role="switch" id="glass-effects" ${p.glass==='full'?'checked':''}><i aria-hidden="true"></i></label><label class="check"><input type="checkbox" id="appearance-auto-opacity" ${p.opacity==='auto'?'checked':''} ${p.glass!=='full'?'disabled':''}> Opacidad automática</label>${range('opacity','Opacidad de las tarjetas',70,100,p.opacity==='auto'?94:p.opacity,' %',p.opacity==='auto'||p.glass!=='full')}${range('blur','Desenfoque del cristal',0,32,p.blur,' px',p.glass!=='full')}${select('glassBehavior','Al cambiar colores o estilos',[['keep','Conservar Liquid Glass'],['free','Usar el efecto de cada estilo']])}${select('spaceTint','Color de Mi espacio',[['linked','Combinar con el color elegido'],['neutral','Mantener tonos neutros']])}${select('borderWidth','Grosor de los bordes',[[0,'Sin borde'],[1,'Fino'],[2,'Medio'],[3,'Grueso']])}<p class="help">La transparencia depende del dispositivo y sus ajustes de accesibilidad.</p>${reset('cards')}</details>
  <details class="panel personalization-panel" data-view-key="personal-text"><summary>Texto, tamaño y espaciado</summary><div class="fields">${select('font','Tipografía',[['system','Sistema'],['rounded','Redondeada'],['serif','Clásica'],['mono','Monoespaciada']])}<label>Tamaño del texto<select id="appearance-text-size"><option value="normal" ${p.textSize==='normal'?'selected':''}>Normal</option><option value="large" ${p.textSize==='large'?'selected':''}>Grande</option><option value="extra" ${p.textSize==='extra'?'selected':''}>Muy grande</option></select></label></div>${select('spacing','Separación entre elementos',[['compact','Compacta'],['comfortable','Cómoda'],['airy','Amplia']])}<div class="fields">${select('lineHeight','Separación entre líneas',[[1.4,'Ajustada'],[1.6,'Normal'],[1.9,'Amplia']])}${select('textWeight','Grosor del texto',[[400,'Normal'],[500,'Medio'],[600,'Marcado']])}</div>${select('contentWidth','Ancho del contenido en ordenador',[[900,'Estrecho'],[1120,'Medio'],[1280,'Amplio'],[1440,'Máximo']])}${reset('text')}</details>
  <details class="panel personalization-panel" data-view-key="personal-comfort"><summary>Comodidad y pantalla de inicio</summary><label>Aspecto<select id="appearance-theme"><option value="dark" ${p.theme==='dark'?'selected':''}>Oscuro</option><option value="light" ${p.theme==='light'?'selected':''}>Claro</option></select></label><label class="check"><input type="checkbox" id="appearance-reduce-motion" ${p.motion==='reduced'?'checked':''}> Reducir animaciones</label><label>Al abrir Ritmo, ir a<select id="appearance-start"><option value="home" ${p.start==='home'?'selected':''}>Hoy</option><option value="train" ${p.start==='train'?'selected':''}>Entrenar</option><option value="menu" ${p.start==='menu'?'selected':''}>Comidas</option></select></label></details>
  <details class="panel personalization-panel" data-view-key="personal-saved"><summary>Mis estilos y archivos</summary><form data-form="save-appearance"><label>Nombre del estilo<input name="styleName" maxlength="40" required placeholder="Ej. Mi estilo de gimnasio"></label><button class="secondary">Guardar estilo actual</button></form><div class="saved-style-list">${savedStyles.map(s=>`<div class="saved-style"><strong>${esc(s.name)}</strong><div class="toolbar">${button('apply-saved-style','Aplicar',`data-id="${esc(s.id)}"`)}${button('remove-saved-style','Eliminar',`data-id="${esc(s.id)}"`)}</div></div>`).join('')||'<p class="help">Aún no has guardado estilos. Puedes guardar hasta 12.</p>'}</div><div class="toolbar">${button('export-appearance','Exportar estilo actual')}<label class="file-label">Importar estilo<input type="file" id="import-appearance" accept="application/json,.json" aria-label="Seleccionar estilo de Ritmo"></label></div><p class="help">Los archivos solo contienen apariencia, sin perfil ni registros de salud.</p></details>
  <div class="personalization-footer">${button('reset-appearance','Restablecer apariencia')}<p class="help" id="appearance-save-status" role="status">Restablecer no borra tus estilos guardados, perfil ni entrenamientos.</p></div>`;
}
